const DICT={}; ROWS.forEach(r=>{DICT[r[0]]={id:r[1],tr:r[2],fr:r[3],uk:r[4]};});
const UIL=()=>{ const L=S.lang||S.guide||'ar'; return L==='eg'?'ar':L; };
const IS_AR=()=>UIL()==='ar';
function T(k,...a){ const L=UIL(); let t=k; if(L!=='ar'){ const r=DICT[k]; if(r&&r[L]) t=r[L]; } return t.replace(/\{(\d)\}/g,(m,i)=>a[+i]!==undefined?a[+i]:''); }
